/**
 * Owns its own index connection (WAL) so the engine's catalog lock is never
 * held across a culling pass. Calls are synchronous; dispatch off the main
 * thread for large queues.
 */
public protocol CullSessionProtocol: AnyObject, Sendable {
    
    /**
     * Assign an existing face to an existing persistent identity. Moving resets
     * confirmation; confirm separately to protect it from automatic refits.
     */
    func assignPersonFace(face: PersonFace, personId: String) throws 
    
    func assistStatus() throws  -> AssistStatus
    
    /**
     * Confirm (`true`) or unconfirm (`false`) an existing face assignment.
     */
    func confirmPersonFace(face: PersonFace, confirmed: Bool) throws 
    
    /**
     * Applies the listed suggestions as one undo step and teaches the learner.
     * Fails without writing anything when a suggestion is stale, unknown or
     * was dismissed.
     */
    func confirmSuggestions(imageIds: [String]) throws  -> CullUpdate
    
    /**
     * Rejects (dismisses) suggestions: they stop showing and cannot be
     * confirmed until assistance is switched again. Nothing is written.
     */
    func dismissSuggestions(imageIds: [String]) throws 
    
    /**
     * Faces of one image, in detection order, with identities. Empty when the
     * image has no analysed faces.
     */
    func faceStrip(imageId: String) throws  -> [FaceChipInfo]
    
    /**
     * Per-person filter: frames where `person_id` appears; with
     * `eyes_closed_below`, only frames where that person's eyes-open proxy is
     * below the threshold (review only; never a decision).
     */
    func framesWithPerson(personId: String, eyesClosedBelow: Double?) throws  -> [String]
    
    /**
     * Explicit merge, target name wins. Does not export sidecars.
     */
    func mergePeople(targetId: String, sourceId: String) throws 
    
    /**
     * Rename/clear an identity and update the library's display names. Requires
     * a library-backed session; XMP export is strictly opt-in. Coordinates use
     * indexed analysis-preview dimensions, never RAW dimensions.
     */
    func namePerson(personId: String, name: String?, options: PeopleNameOptions) throws 
    
    /**
     * People in this queue, most frequent first. `refresh` ingests new faces
     * and runs the job's periodic refit; use `refresh_people(true)` to force it.
     */
    func people(refresh: Bool) throws  -> [PersonInfo]
    
    /**
     * Read-only catalog suggestions. Accept explicitly with merge/assignment;
     * neither names nor assignments are changed by requesting suggestions.
     */
    func peopleNameSuggestions(threshold: Float?) throws  -> [PeopleNameSuggestion]
    
    /**
     * Read persisted names and confirmation state, including manual assignments
     * to faces without usable descriptors. This never runs a clustering job.
     */
    func personAssignments(imageId: String) throws  -> [PersonAssignmentInfo]
    
    /**
     * Incremental ingestion with periodic refits, or an explicit forced refit.
     * Blocking: invoke on the host worker queue, never the UI thread.
     */
    func refreshPeople(force: Bool) throws  -> PeopleJobResult
    
    /**
     * Reorders the review queue by the last `review` (navigation order only;
     * cursor and undo positions are preserved). Returns the new order.
     */
    func reorderQueue() throws  -> [String]
    
    /**
     * Predicts every frame (read-only) in review order: likely keepers first,
     * uncertain next, likely rejects last. Regenerate after new signals,
     * decisions or confirmations.
     */
    func review() throws  -> [KeepPrediction]
    
    /**
     * Switches assistance. The learner is library-local (app support
     * `cull-learning/`) and survives sessions.
     */
    func setAssistMode(mode: AssistMode) throws  -> AssistStatus
    
    /**
     * Split selected members into a new unnamed identity (caller supplies a
     * unique ID). Confirmations reset. Does not export sidecars.
     */
    func splitPerson(sourceId: String, newId: String, faces: [PersonFace]) throws 
    
    func albums() throws  -> [AlbumInfo]
    
    func autoAdvance() throws  -> Bool
    
    func basketTarget() throws  -> String?
    
    func bestInGroup(group: UInt32) throws  -> String
    
    func canRedo() throws  -> Bool
    
    func canUndo() throws  -> Bool
    
    /**
     * Latest catalog change sequence the queue reflects.
     */
    func changeSequence() throws  -> UInt64
    
    func current() throws  -> String?
    
    func currentGroup() throws  -> UInt32?
    
    /**
     * With assistance on (`set_assist_mode`), a Keep/Reject also teaches the
     * library's learner.
     */
    func decide(decision: Decision) throws  -> CullUpdate
    
    /**
     * A different decision per image as one undo step ("choose this" in
     * compare keeps one frame and rejects the other).
     */
    func decideEach(decisions: [ImageDecision]) throws  -> CullUpdate
    
    func decideImages(imageIds: [String], decision: Decision) throws  -> CullUpdate
    
    /**
     * Review list only: applies nothing and records no history. Apply the
     * user's confirmed subset with `decide_images(.., Reject)`.
     */
    func defectSweep(thresholds: [DefectThreshold]) throws  -> [DefectCandidate]
    
    /**
     * Derived, read-only status per image (library.json read once).
     */
    func derivedStatuses(imageIds: [String]) throws  -> [ImageStatus]
    
    func grade(grade: UInt8) throws  -> CullUpdate
    
    func gradeImages(imageIds: [String], grade: UInt8) throws  -> CullUpdate
    
    /**
     * Scores may have changed since the last call: every best is picked afresh.
     */
    func groups() throws  -> [CullGroup]
    
    func images() throws  -> [SessionImage]
    
    /**
     * Keeps the group's suggested best and rejects the rest as one undo step.
     */
    func keepBestRejectRest(group: UInt32) throws  -> GroupDecision
    
    func libraryPath() throws  -> String?
    
    /**
     * Empty name clears the mark.
     */
    func mark(name: String) throws  -> CullUpdate
    
    func markImages(imageIds: [String], name: String) throws  -> CullUpdate
    
    func nextGroup() throws  -> String?
    
    func nextInGroup() throws  -> String?
    
    func position() throws  -> UInt32?
    
    func prevGroup() throws  -> String?
    
    func prevInGroup() throws  -> String?
    
    /**
     * Images whose embedded preview could not be read for near-duplicate
     * grouping, with the reason. They remain reviewable.
     */
    func previewErrors() throws  -> [String]
    
    func redo() throws  -> CullUpdate?
    
    /**
     * Safe delete inside an album: membership only, files untouched. Undoable.
     */
    func removeFromAlbum(album: String, imageIds: [String]) throws  -> CullUpdate
    
    func selection(imageId: String) throws  -> Selection
    
    func setAutoAdvance(enabled: Bool) throws 
    
    func setBasket(imageIds: [String], add: Bool) throws  -> CullUpdate
    
    /**
     * Membership flags in later updates refer to the new target.
     */
    func setBasketTarget(name: String) throws 
    
    func setCurrent(imageId: String) throws 
    
    func setLibrary(path: String) throws 
    
    func setPosition(position: UInt32) throws 
    
    /**
     * Applies catalog changes committed since the last sync (or open) to the
     * queue in place: new images join at their queue position and burst,
     * removed ones leave, and only the affected groups are recomputed. The
     * cursor and the undo/redo history are kept (steps of removed images are
     * dropped). Call it on `EngineEvent::LibraryChanged`.
     */
    func syncChanges() throws  -> QueueDelta
    
    func toggleBasket() throws  -> CullUpdate
    
    /**
     * Returns None when there is nothing to undo.
     */
    func undo() throws  -> CullUpdate?
    
}
