#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDevelopSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = DevelopSession

    public static func lift(_ handle: UInt64) throws -> DevelopSession {
        return DevelopSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: DevelopSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DevelopSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: DevelopSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDevelopSession_lift(_ handle: UInt64) throws -> DevelopSession {
    return try FfiConverterTypeDevelopSession.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDevelopSession_lower(_ value: DevelopSession) -> UInt64 {
    return FfiConverterTypeDevelopSession.lower(value)
}






public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * RAW cache misses return pending immediately; PreviewReady signals completion.
     */
    func embeddedPreview(imageId: String, maxPx: UInt32) throws  -> PreviewResponse
    
    func getRecipe(imageId: String) throws  -> String
    
    func indexFolder(path: String) throws  -> FolderHandle
    
    func listImages(query: ImageQuery) throws  -> [ImageSummary]
    
    /**
     * Setting a listener also starts watching the catalog for writes made
     * elsewhere (reported as `LibraryChanged`).
     */
    func setEventListener(listener: EngineEventListener?) 
    
    func setRecipeJson(imageId: String, json: String) throws 
    
    func setSelection(imageId: String, selection: Selection) throws 
    
    /**
     * Review queue "accept": marks the agent edit accepted and teaches the
     * library's style profile the image's final settings (accepted changes
     * included). The recipe is never altered by accepting.
     */
    func acceptAgentEdit(imageId: String, libraryFolder: String) throws  -> AgentAcceptResult
    
    /**
     * The latest agent run's provenance and review item, if the image has one.
     */
    func agentProvenance(imageId: String) throws  -> AgentProvenance?
    
    /**
     * Review queue "revert": the agent group at 0 % as one undoable step
     * (later manual edits kept); the steps stay in history.
     */
    func revertAgentEdit(imageId: String, groupId: UInt32) throws 
    
    /**
     * Runs the agent's base edit (or an instruction redo) on each image and
     * returns the review queue. Blocking: call off the main thread; cancel
     * between images with `cancel`. Close develop sessions on these images
     * first (their pending saves would overwrite the agent's steps).
     */
    func runAgent(request: AgentRunRequest, cancel: CancelFlag, listener: AgentRunListener?) throws  -> AgentRunReport
    
    /**
     * Cold-start answers (docs/10 §2); learned samples are kept.
     */
    func setStyleQuestionnaire(libraryFolder: String, answers: StyleQuestionnaire) throws  -> StyleProfileStatus
    
    /**
     * The library's style profile (a default, untrained one when none is saved).
     */
    func styleProfileStatus(libraryFolder: String) throws  -> StyleProfileStatus
    
    /**
     * Learns from every photo in the folder whose history has user edits
     * (their last user-confirmed state). Blocking; progress per photo.
     */
    func trainStyleProfile(libraryFolder: String, cancel: CancelFlag, listener: AgentRunListener?) throws  -> StyleProfileStatus
    
    /**
     * Computes real culling signals for one image from its displayed preview
     * (≤ 1024 px): classical quality (`sharpness`, `motion_blur`, `noise`,
     * per-channel exposure/clipping, `quality`, plus `highlight_clipping` = the
     * worst channel) and, when asked, faces (`face_sharpness`, `eyes_open`
     * aggregates and per-face rows with SFace descriptors). Blocking; call off
     * the main thread and loop over a shoot (the host shows progress).
     */
    func analyzeImage(imageId: String, options: AnalysisOptions) throws  -> AnalysisResult
    
    /**
     * Test aid (like `set_score`): replaces an image's faces with synthetic
     * detections measured on a `width × height` preview. Landmarks are placed
     * canonically inside each box. Producers are the face analysis above.
     */
    func setFaces(imageId: String, faces: [FaceInput], width: UInt32, height: UInt32) throws 
    
    /**
     * Latest change sequence of the catalog (0 when nothing was ever written).
     */
    func changeSequence() throws  -> UInt64
    
    /**
     * Net changes after `sequence` (see `LibraryChanges`).
     */
    func changesSince(sequence: UInt64) throws  -> LibraryChanges
    
    /**
     * Drops the catalog rows of images whose files are gone (after "Delete
     * from Disk"); images whose files still exist are kept. Open sessions see
     * them leave through `sync_changes`. Returns the number removed.
     */
    func forgetMissing(imageIds: [String]) throws  -> UInt32
    
    /**
     * Opens (without creating) the library document at `path`, conventionally
     * `<folder>/library.json`, and aligns the catalog's keyword hierarchy.
     */
    func openLibrary(path: String) throws  -> LibraryStore
    
    /**
     * Opens a develop session on an indexed RAW image. Blocking (decodes the
     * raw): call off the main thread. One session per visible image.
     */
    func openDevelopSession(imageId: String) throws  -> DevelopSession
    
    func deleteExportPreset(name: String) throws 
    
    /**
     * Exports `target` with `settings_json` (`ExportOptions`) into its
     * destination. Blocking: call off the main thread. Per-image failures
     * (unreadable source, existing file with `on_conflict: skip`, …) are
     * reported per item; settings, destination and naming problems fail the
     * whole call before anything is written. After a cancel the report lists
     * the images already written; nothing half-written is left behind.
     */
    func exportBatch(target: ExportTarget, settingsJson: String, listener: ExportProgressListener?, cancel: CancelFlag?) throws  -> ExportReport
    
    /**
     * Export presets: the shipped ones (installed into the app directory on
     * first use, then editable like any other) in their order, then the
     * user's alphabetically.
     */
    func exportPresets() throws  -> [ExportPreset]
    
    func renameExportPreset(name: String, newName: String) throws 
    
    /**
     * Renders one photo for printing: develop settings, orientation, fit to
     * the box, print sharpening, then colour for the chosen handling.
     * Blocking; `cancel` stops between stages.
     */
    func renderForPrint(request: PrintRenderRequest, cancel: CancelFlag?) throws  -> PrintImage
    
    /**
     * Re-installs the shipped presets (replacing edits to them; others stay).
     */
    func restoreDefaultExportPresets() throws 
    
    /**
     * Creates or replaces the preset called `name`.
     */
    func saveExportPreset(name: String, settingsJson: String) throws 
    
    /**
     * Reads (a temporary copy of) the catalog. Blocking: call off the main thread.
     */
    func openLrcat(path: String) throws  -> LrcatImport
    
    /**
     * Recursive folder queue over already-indexed images (call `index_folder`
     * first). The library defaults to `<folder>/library.json`. Auto-advance is
     * off; hosts move the cursor with `set_current`/navigation.
     */
    func openCullSession(folder: String) throws  -> CullSession
    
    /**
     * Filtered queue. Zero limit means all matches. Call `set_library` before
     * basket operations.
     */
    func openCullSessionForQuery(query: ImageQuery) throws  -> CullSession
    
    /**
     * Stores the latest value of an AI signal (e.g. "focus", "closed_eyes").
     * Producers are ML jobs; the app uses it only for synthetic test scores.
     */
    func setScore(imageId: String, signal: String, value: Double, model: String) throws 
    
    /**
     * Whether this catalog has a tether session on this thread.
     */
    func tetherActive()  -> Bool
    
    func tetherCapture() throws 
    
    /**
     * Connected cameras. During a session this asks the session's own backend
     * (fresh battery / remaining-frame readouts) instead of opening another.
     */
    func tetherDevices() throws  -> [TetherDevice]
    
    func tetherLiveView() throws  -> Data
    
    /**
     * Returns frames as well as notifying the optional listener. Callbacks run
     * outside the session borrow, so UI code may safely reenter tether commands.
     * The ingest worker writes the catalog on its own connection; each poll
     * announces those writes as `EngineEvent::LibraryChanged` (frames join the
     * library through the change feed, not a reload).
     */
    func tetherPoll() throws  -> [TetherFrame]
    
    func tetherSetListener(listener: TetherEventListener?) throws 
    
    func tetherStart(sessionFolder: String, naming: String) throws 
    
    func tetherStop() throws  -> [TetherFrame]
    
    /**
     * Hidden test aid: `Some(folder)` makes the next sessions on this thread use a
     * test camera that shoots that folder's images (on `tether_capture`, and every
     * `interval_ms` when non-zero); `None` restores ImageCaptureCore.
     */
    func tetherUseFake(sourceFolder: String?, intervalMs: UInt64) throws 
    
    func aiMetadataSettings() throws  -> AiMetadataSettings
    
    /**
     * Any combination of tasks; `force` recomputes cached results.
     */
    func analyzeUnderstanding(imageIds: [String], tasks: [UnderstandingTask], force: Bool) throws  -> UInt64
    
    /**
     * When "auto-suggest on import" is on, starts a keyword job for the
     * photos (only uncached ones do work). None when the setting is off.
     */
    func autoSuggest(imageIds: [String]) throws  -> UInt64?
    
    /**
     * Cancels a queued or running job (results already stored stay).
     */
    func cancelUnderstandingJob(id: UInt64) throws 
    
    /**
     * Generates a caption and alt text for the photos in the background.
     */
    func caption(imageIds: [String]) throws  -> UInt64
    
    /**
